import { 技能类别列表, 罪孽列表, 攻击类型列表, 守备类型列表, 时机列表, 硬币类型列表, } from '../共享/技能常量';
/** UI 选项别名 (历史命名, 统一指向 技能常量 的列表) */
export const 罪孽选项 = 罪孽列表;
export const 攻击类型选项 = 攻击类型列表;
export const 类别选项 = 技能类别列表;
export const 守备类型选项 = 守备类型列表;
export const 时机选项 = 时机列表;
export const 硬币类型选项 = 硬币类型列表;
export const 罪孽颜色 = {
    暴怒: '#e04b3a',
    色欲: '#e05297',
    怠惰: '#e0a53a',
    暴食: '#4fb04f',
    忧郁: '#3aa0e0',
    傲慢: '#8a5de0',
    嫉妒: '#e0d23a',
};
/** 依据模板与用户输入, 创建一份可编辑的技能草稿 (深拷贝, 并补齐可编辑数组) */
export function 建草稿(定义) {
    if (!定义) {
        return { 名称: '', 类别: '战斗', 罪孽: '暴怒', 攻击类型: '打击', 硬币: [], 攻击等级修正: 0, 攻击容量: 1, 效果: '', 描述: '', effects: [] };
    }
    const 草稿 = klona(定义);
    草稿.硬币 = 规范化硬币(草稿).map(项 => ({ ...项, 命中效果: (项.命中效果 ?? []).map(效果 => ({ ...效果 })) }));
    草稿.effects = (草稿.effects ?? []).map(效果 => ({ ...效果 }));
    return 草稿;
}
/** 将 硬币 派生字段与现有 硬币威力 / 硬币类型 数组同步 */
export function 规范化硬币(定义) {
    const 补齐 = (项, 下标) => ({
        威力: 项.威力 ?? 定义.硬币威力?.[下标] ?? 0,
        类型: 项.类型 ?? 定义.硬币类型?.[下标] ?? '普通',
        命中效果: 项.命中效果 ?? [],
    });
    if (Array.isArray(定义.硬币) && 定义.硬币.length)
        return 定义.硬币.map(补齐);
    const 威力表 = 定义.硬币威力 ?? [];
    const 类型表 = 定义.硬币类型 ?? [];
    return 威力表.map((威力, 下标) => ({ 威力, 类型: 类型表[下标] ?? '普通', 命中效果: [] }));
}
